"use client";

import Link from "next/link";
import { useActionState } from "react";
import { signInWithCredentials, signInWithGoogle, signUp } from "./actions";

const input = "w-full rounded border border-black/20 bg-transparent px-3 py-2 text-sm dark:border-white/20";
const button = "w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-60";

export function AuthForm({ mode, callbackUrl }: { mode: "signin" | "signup"; callbackUrl?: string }) {
  const isSignUp = mode === "signup";
  const [state, action, pending] = useActionState(isSignUp ? signUp : signInWithCredentials, undefined);

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your account" : "Sign in to Notely"}</h1>

      <form action={action} className="mt-6 space-y-3">
        <input type="hidden" name="callbackUrl" value={callbackUrl ?? ""} />
        {isSignUp && <input className={input} name="name" placeholder="Name" autoComplete="name" required />}
        <input className={input} name="email" type="email" placeholder="Email" autoComplete="email" required />
        <input
          className={input}
          name="password"
          type="password"
          placeholder="Password"
          autoComplete={isSignUp ? "new-password" : "current-password"}
          minLength={isSignUp ? 8 : undefined}
          required
        />
        {state?.error && <p role="alert" className="text-sm text-red-600">{state.error}</p>}
        <button className={button} disabled={pending}>{isSignUp ? "Sign up" : "Sign in"}</button>
      </form>

      <form action={signInWithGoogle} className="mt-3">
        <input type="hidden" name="callbackUrl" value={callbackUrl ?? ""} />
        <button className={`${button} !bg-transparent !text-foreground border border-black/20 dark:border-white/20`}>
          Continue with Google
        </button>
      </form>

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>Already have an account? <Link className="underline" href="/signin">Sign in</Link></>
        ) : (
          <>No account? <Link className="underline" href="/signup">Sign up</Link></>
        )}
      </p>
    </main>
  );
}
